package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TaskCost080Test {
    static JSONObject spec(int n){try(var in=TaskCost080.class.getResourceAsStream("/procedures080-protocol.json")){return new JSONObject(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("calibration").getJSONObject(n);}catch(Exception e){throw new RuntimeException(e);}}
    static JSONObject workload(){return new JSONObject().put("retain",false).put("skill",false);}
    static JSONObject measured(String id,String mode,double ms,int n){return new JSONObject().put("id",id).put("mode",mode).put("totalMillis",ms).put("eligible",true).put("completed",true).put("code","same-code").put("profile",TaskCost080.profile()).put("workload",workload()).put("task",new JSONObject().put("input",n)).put("spec",spec(n)).put("usedMemory",mode.equals("memory")).put("preferred","two-stage").put("receiptId","owned-memory").put("warm",true);}
    static JSONObject model(double first,double second){return new JSONObject().put("id","test-model").put("profile",TaskCost080.profile()).put("pairs",new JSONArray().put(TaskCost080.pair(measured("s1","simple",10000,0),measured("m1","memory",10000-first,0))).put(TaskCost080.pair(measured("s2","simple",12000,1),measured("m2","memory",12000-second,1))));}
    static JSONObject candidate(){return new JSONObject().put("id","owned-memory").put("family","two-stage").put("warm",true).put("distance",.01);}
    @Test public void completeDurationsDetermineSavingsIncludingPostExecutionWork(){var m=model(3000,4000);var e=TaskCost080.estimate(candidate(),spec(0),workload(),m);assertTrue(e.getBoolean("available"));assertEquals(11000,e.getDouble("simpleMillis"),0);assertEquals(7500,e.getDouble("memoryMillis"),0);assertEquals(3500,e.getDouble("savingMillis"),0);assertTrue(e.getDouble("marginMillis")>=500);assertTrue(TaskCost080.choose(spec(0),new JSONArray().put(candidate()),workload(),m).getBoolean("useMemory"));}
    @Test public void uncertainOrNegativeSavingsDoNotSpendOnMemory(){for(var m:new JSONObject[]{model(-3000,-1000),model(5000,-5000)})assertFalse(TaskCost080.choose(spec(0),new JSONArray().put(candidate()),workload(),m).getBoolean("useMemory"));}
    @Test public void coldProfileWorkloadAndReceiptMismatchHaveNoInventedEstimate(){var m=model(3000,4000);var c=candidate();c.put("warm",false);assertFalse(TaskCost080.estimate(c,spec(0),workload(),m).getBoolean("available"));c=candidate().put("id","another");assertFalse(TaskCost080.estimate(c,spec(0),workload(),m).getBoolean("available"));assertFalse(TaskCost080.estimate(candidate(),spec(0),workload().put("retain",true),m).getBoolean("available"));m.getJSONObject("profile").put("cpus",999);assertFalse(TaskCost080.estimate(candidate(),spec(0),workload(),m).getBoolean("available"));}
    @Test public void duplicateTaskDoesNotSatisfyMinimumCoverage(){var m=model(3000,4000);m.getJSONArray("pairs").put(1,m.getJSONArray("pairs").getJSONObject(0));assertFalse(TaskCost080.estimate(candidate(),spec(0),workload(),m).getBoolean("available"));}
    @Test public void mismatchedOrUnverifiedPairsAreRejected(){var s=measured("s","simple",1000,0);for(String field:new String[]{"eligible","completed"})assertThrows(IllegalArgumentException.class,()->TaskCost080.pair(new JSONObject(s.toString()).put(field,false),measured("m","memory",900,0)));assertThrows(IllegalArgumentException.class,()->TaskCost080.pair(s,measured("m","memory",900,1)));assertThrows(IllegalArgumentException.class,()->TaskCost080.pair(s,measured("m","memory",900,0).put("code","changed")));assertThrows(IllegalArgumentException.class,()->TaskCost080.pair(s,measured("m","memory",900,0).put("usedMemory",false)));assertThrows(IllegalArgumentException.class,()->TaskCost080.pair(s,measured("m","memory",0,0)));assertThrows(IllegalArgumentException.class,()->TaskCost080.pair(s,measured("s","memory",900,0)));}
    @Test public void noCalibrationFallsBackWithoutMintingProof(){var d=TaskCost080.choose(spec(0),new JSONArray().put(candidate()),workload(),new JSONObject());assertFalse(d.getBoolean("useMemory"));assertFalse(d.getJSONObject("cost080").getBoolean("available"));assertEquals("direct",d.getString("preferred"));}
    @Test public void directRecipeAndMissingRoleStaySimple(){var c=candidate().put("family","direct");assertFalse(TaskCost080.estimate(c,spec(0),workload(),model(4000,5000)).getBoolean("available"));var changed=spec(0);changed.getJSONArray("targets").getJSONObject(0).put("sourceId","unknown");assertFalse(TaskCost080.estimate(candidate(),changed,workload(),model(4000,5000)).getBoolean("available"));}
}
